g_trust_path_invalid\":\"trust envelope 路径非法。\",\"runtime_config_trust_read_failed\":\"trust envelope 读取 IO 失败。\",\"runtime_config_trust_too_large\":\"trust envelope 超出尺寸上限。\"},\"runtime_config_package\":{\"forbidden_runtime_categories\":[\"content_release\",\"rollout_stage\",\"channel\",\"secret\"],\"max_future_skew_seconds\":300,\"max_lifetime_seconds\":86400,\"signature_algorithm\":\"ed25519\",\"signed_payload_excludes\":[\"signature\"],\"source_identity\":{\"accepted_authorities\":[\"package_input_capsule\",\"audited_git_identity\"],\"git_sha_format\":\"lowercase_40_hex\",\"tree_digest_formats\":[\"sha1\",\"sha256\"]}},\"runtime_config_supply_modes\":[\"external_runtime_package\",\"build_time_self_supply\"],\"runtime_config_trust\":{\"build_profiles\":[\"nonprod\",\"prod\"],\"signature_algorithm\":\"ed25519\"},\"runtime_document_content_sources\":{\"app-offline-bootstrap-document\":\"bundled_snapshot\",\"app-runtime-config-package\":\"remote\"},\"runtime_value_keys\":{\"appDownloadBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"appRuntimeEnv\":{\"category\":\"launch\",\"required\":true,\"type\":\"string\"},\"gatewayBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"legalBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"mediaAvatarCdnBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"mediaImageCdnBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"mediaUploadBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"mediaVideoCdnBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"publicWebBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"realtimeBaseUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"},\"rtcMediaConnectionUrl\":{\"category\":\"endpoint\",\"required\":true,\"type\":\"string\"}},\"schema_id\":\"app_launch_manifest\",\"schemas\":{\"app_effective_launch_manifest\":{\"additional_fields\":false,\"constraints\":[\"target 必须映射到 target_environment 中声明的 environment。\",\"contentSource 必须等于 content_source_policy[environment] 且与 runtime_document_content_sources[文档 schema] 一致；离线文档的签名 contentSource 必须同值。在线包不得追加 contentSource 字段改变既有签名形状。\",\"requiresLocalTransport 必须等于 contentSource=remote 且 target 属于 local_transport_targets；离线 transport.required=false 且 ports/lease/receipt 全空，禁止产生在线 readiness。\",\"transport.required=true 只允许 local_transport_targets，且端口集合必须相等，receipt digest 与 consumer lease ID 必须是 sha256 identity。\",\"transport.required=false 时端口和本地 transport identity 必须为空；Remote 的 package-only 或未附带设备 transport 的 handoff 不得成为 runtime UAT 证据。bundled_snapshot 页面 UAT 绑定实际设备、安装制品、签名快照与 exact source candidate，不要求在线 transport、Provider、登录或服务端 activation。\",\"prod-hosted 必须令 local transport 为 false，且全部端口与本地 transport identity 为空。\",\"buildProfile、launchPolicy 必须与 environment 满足 launch_policies 和 app_artifact_manifest.build_profiles 的映射；launchProvenance 必须来自 app_artifact_manifest.launch_provenances 且不得改变业务行为，runtimeConfigSupplyMode 必须来自 runtime_config_supply_modes。\",\"runtimeConfigPackageDigest 必须等于 handoff 所携带 runtimeConfigPackage 的 digest_contract canonical JSON 摘要。\",\"runtimeConfigTrustEnvelopeDigest 必须等于已安装 AppArtifact/Web bootstrap 内匹配 buildProfile 的 runtime_config_trust_envelope 摘要；handoff 只携带摘要，不复制 keyring。\",\"本清单不携带内容 release 身份；内容激活身份只由 Content API 响应在运行时下发。\"],\"fields\":{\"buildProfile\":{\"allowed_values\":[\"nonprod\",\"prod\"],\"type\":\"string\"},\"contentSource\":{\"allowed_values\":[\"bundled_snapshot\",\"remote\"],\"type\":\"string\"},\"entrypoint\":{\"allowed_values\":[\"lib/main_alpha.dart\",\"lib/main_prod.dart\"],\"source\":\"content_source_entrypoints[contentSource]\",\"type\":\"string\"},\"environment\":{\"allowed_values\":[\"alpha\",\"beta\",\"gamma\",\"prod\"],\"type\":\"string\"},\"launchPolicy\":{\"allowed_values\":[\"test_live\",\"prod_release\"],\"type\":\"string\"},\"launch